def nice_ticks(vmin: float, vmax: float, target: int = 5):
    """返回 (tick 值列表, 轴下界, 轴上界)，使用 1/2/5×10^k 的整齐刻度。"""
    if vmax == vmin:
        vmax = vmin + 1
    raw = (vmax - vmin) / max(1, target)
    mag = 10 ** (len(str(int(abs(raw)))) - 1) if abs(raw) >= 1 else 10 ** -2
    for m in (1, 2, 2.5, 5, 10):
        step = m * mag
        if raw <= step:
            break
    lo = step * (int(vmin / step) - 1) if vmin < 0 else 0
    if vmin < 0:
        lo = step * int(vmin / step)
        while lo > vmin:
            lo -= step
    hi = lo
    while hi < vmax:
        hi += step
    ticks = []
    t = lo
    while t <= hi + step * 1e-9:
        ticks.append(round(t, 10))
        t += step
    return ticks, lo, hi

