def axis_bbox(box, uu, vv, margin=14.0):
    """把 (u,v) 局部框投影回画布，得到轴对齐的检索窗口。"""
    us = [box[0], box[2]]
    vs = [box[1], box[3]]
    xs, ys = [], []
    for u in us:
        for v in vs:
            xs.append(u * uu[0] + v * vv[0])
            ys.append(u * uu[1] + v * vv[1])
    return (min(xs) - margin, min(ys) - margin, max(xs) + margin, max(ys) + margin)

def scan(im, win, color):
    px = im.load()
    strict, blended = [], []
    x0 = max(0, int(win[0]))
    y0 = max(0, int(win[1]))
    x1 = min(im.width, int(win[2]) + 1)
    y1 = min(im.height, int(win[3]) + 1)
    for yy in range(y0, y1):
        for xx in range(x0, x1):
            p = px[xx, yy]
            if p == color:
                strict.append((xx + 0.5, yy + 0.5))
                continue
            if blend_alpha(p, color) is not None:
                blended.append((xx + 0.5, yy + 0.5))
    return strict, blended

