def alpha_identity(path_a: Path, path_b: Path):
    with Image.open(path_a) as s:
        s.load()
        ia = s.convert("RGBA")
    with Image.open(path_b) as s:
        s.load()
        ib = s.convert("RGBA")
    pa, pb = ia.load(), ib.load()
    w, h = ia.size
    assert ib.size == ia.size, "两版尺寸必须一致"
    diff = 0
    for y in range(h):
        for x in range(w):
            if pa[x, y][3] != pb[x, y][3]:
                diff += 1
    return {"size": [w, h], "alpha_mismatched_pixels": diff,
            "note": "彩色版与纯黑版由同一个 symbol() 生成、只换调色板，alpha 通道应逐像素相同",
            "passed": diff == 0}

