def pick_size(text: str):
    """返回 (字号, 行数, 命中的规则分支)。"""
    for s in LADDER:
        if len(wrap(text, s, TITLE_W)) <= PREFERRED_LINES:
            return s, len(wrap(text, s, TITLE_W)), \
                f"阶梯自 {s}px 起，满足 ≤{PREFERRED_LINES} 行"
    for s in LADDER:
        if len(wrap(text, s, TITLE_W)) <= MAX_LINES:
            return s, len(wrap(text, s, TITLE_W)), \
                f"≤{PREFERRED_LINES} 行不可达，自 {s}px 起满足 ≤{MAX_LINES} 行"
    return LADDER[-1], len(wrap(text, LADDER[-1], TITLE_W)), \
        f"全部阶梯均超过 {MAX_LINES} 行，落到硬底线 {MIN_TITLE_PX}px"

