def char_em(ch: str) -> float:
    """单字宽度（em）。全角 1.0，拉丁按字形分类。"""
    if is_fullwidth(ch):
        return 1.0
    if ch == " ":
        return 0.26
    if ch in "iljtfr.,;:'!|[]()":
        return 0.30
    if ch in "mwMW":
        return 0.83
    if ch.isdigit() or ch.isupper():
        return 0.62
    if ch.isalpha():
        return 0.55
    return 0.42

