        "px_per_unit": round((grid[0] - grid[-1]) / (ticks[0] - ticks[-1]), 4),
        "baseline_value_at_y565": ticks[-1],
        "min_tick": ticks[-1],
        "formula": "value(y) = 100 + (565 - y) / 2.7",
        "truncated": ticks[-1] != 0,
    }

    def value_at(y):
        return round(100 + (565 - y) / 2.7, 1)

    # ---- 柱体（只在 y 250..600 区间找，避开 y≈183 的图例色块）
    def bars(color):
