def est_w(text: str, size: float) -> float:
    """字面宽估算（系数沿用 A14 对本服务实测标定出的 em 表）。"""
    _NARROW = "iljft.,;'`|"
    _MED = "rsz"
    _WIDE = "mw"
    _HEAVY = "<>&@"
    tot = 0.0
    for ch in text:
        o = ord(ch)
        if (0x1100 <= o <= 0x115F or 0x2E80 <= o <= 0x303E or 0x3041 <= o <= 0x33FF
                or 0x3400 <= o <= 0x4DBF or 0x4E00 <= o <= 0x9FFF
                or 0xAC00 <= o <= 0xD7A3 or 0xF900 <= o <= 0xFAFF
                or 0xFE10 <= o <= 0xFE4F or 0xFF00 <= o <= 0xFF60 or 0xFFE0 <= o <= 0xFFE6
                or ch in "—…·“”"):
            tot += 1.0
        elif ch == " ":
            tot += 0.28
        elif ch in _NARROW:
            tot += 0.30
        elif ch in _MED:
            tot += 0.40
        elif ch in _WIDE:
            tot += 0.85
        elif ch in _HEAVY:
            tot += 0.66
        elif ch in ":;":
            tot += 0.42
        elif ch == "/":
            tot += 0.40
        elif ch.isdigit():
            tot += 0.53
        elif ch.isupper():
            tot += 0.70
        elif ch.isalpha():
            tot += 0.60
        else:
            tot += 0.32
    return tot * size


def n_lines(text: str, size: float, box_w: float) -> int:
    return max(1, -(-int(est_w(text, size) * 100) // int(box_w * 100)))

