# 5) 跨帧尺度不变。
    #    面积是「可见面积」：中途帧里单元互相遮挡会把下层单元的可见面积压低，
    #    所以不能拿 f1 当基准。改用**各帧最大值**作基准（遮挡只会变小），
    #    要求每帧每色 ≥ 基准的 50%——这既能抓出「单元消失」，又不受遮挡影响。
    max_area = {}
    for pf in per_frame:
        for c, a in pf["color_area_px"].items():
            max_area[c] = max(max_area.get(c, 0), a)
    for pf in per_frame:
        for c, a in pf["color_area_px"].items():
            if a < 0.5 * max_area[c]:
                problems.append(f'f{pf["frame"]} 颜色 {c} 面积 {a} 不足基准 '
                                f'{max_area[c]} 的一半，疑似单元被遮挡消失或缩小')

input.oldString:
# 5) 跨帧尺度不变：同一颜色的最大内接尺寸按未旋转几何推算，
    #    旋转只会让轴对齐外包框变大/变小，颜色总面积才是尺度不变量。
    ref_area = per_frame[0]["color_area_px"]
    for pf in per_frame[1:]:
        for c, a in pf["color_area_px"].items():
            b = ref_area[c]
            # 同一颜色可能被 2 个单元共用（外圈 8 片用 4 色，各 2 片），
            # 所以只做宽松的相对一致性检查：任一颜色面积不得偏离基准 ±60%
            if abs(a - b) / b > 0.60:
                problems.append(f'f{pf["frame"]} 颜色 {c} 面积 {a} 与 f1 的 {b} 偏差过大')

