    """给定每个双选任务的团队归属，用表调度器构造一个可行排程。"""
    by = {t["id"]: t for t in tasks}
    free = {"design": 0.0, "engineering": 0.0}
    done = {}
    placed = {}
    order = [t["id"] for t in tasks]
    # 按 (依赖数, 时长) 排序只是让结果稳定；真正的就绪判定用 done
    pending = set(order)
    guard = 0
    while pending and guard < 200:
        guard += 1
        progressed = False
        for tid in order:
            if tid not in pending:
                continue
            t = by[tid]
            if not all(d in done for d in t["depends"]):
                continue
            team = assign.get(tid) or t["teams"][0]
            start = max([free[team]] + [done[d] for d in t["depends"]])
            end = start + t["minutes"]
            free[team] = end
            done[tid] = end
            placed[tid] = (start, end, team)
            pending.discard(tid)
            progressed = True
        if not progressed:
            raise RuntimeError(f"依赖无法满足：{sorted(pending)}")
    return placed, free

