def wrap(text: str, size: float, width: float):
    """按实测字宽把文本切成不超过 width 的行。

    不依赖服务端的自动换行：服务端会把溢出盒子的行**静默裁掉**，
    所以这里自己排版、每行一个 Text，行高固定，行数由代码决定。
    CJK 可逐字断行；连续的 ASCII 词（如 Retry-After）尽量不拆。
    """
    lines, cur, cur_w = [], "", 0.0
    tokens, buf = [], ""
    for ch in text:
        if ord(ch) > 0x2E80 or ch == " ":
            if buf:
                tokens.append(buf)
                buf = ""
            tokens.append(ch)
        else:
            buf += ch
    if buf:
        tokens.append(buf)
    for tk in tokens:
        w = em_width(tk, size)
        if cur and cur_w + w > width:
            lines.append(cur)
            cur, cur_w = tk, w
        else:
            cur += tk
            cur_w += w
    if cur:
        lines.append(cur)
    return lines


